// The synthetic phantom of the example, generated by the shoreline crate's ignored export test
// (the same generator as the hosted example), once per test run.
import { execFileSync } from "node:child_process";
import { existsSync, mkdirSync, readFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { fileURLToPath } from "node:url";

const workspace = fileURLToPath(new URL("../../../exes/dwi/", import.meta.url));

export function phantomDir() {
  const dir = join(process.env.TMPDIR || tmpdir(), "dwicorrect-e2e-phantom");
  if (!existsSync(join(dir, "example", "sub-phantom_dwi.nii.gz"))) {
    mkdirSync(dir, { recursive: true });
    execFileSync("cargo", ["test", "--release", "--locked", "-p", "dwi-shoreline", "--test", "synthetic", "export_command_line_phantom", "--", "--ignored"], {
      cwd: workspace,
      env: { ...process.env, SHORELINE_CLI_PHANTOM_DIR: dir },
      stdio: ["ignore", "ignore", "inherit"],
    });
  }
  return dir;
}

/** The example bundle as Playwright file payloads; `skip` leaves out files by name. */
export function exampleFiles({ skip = [] } = {}) {
  const dir = join(phantomDir(), "example");
  const names = ["sub-phantom_dwi.nii.gz", "sub-phantom_dwi.bval", "sub-phantom_dwi.bvec", "sub-phantom_dwi.json", "sub-phantom_dir-reverse_epi.nii.gz", "sub-phantom_dir-reverse_epi.json"];
  return names.filter((name) => !skip.includes(name)).map((name) => ({ name, mimeType: "application/octet-stream", buffer: readFileSync(join(dir, name)) }));
}

/** The phantom's true movement per volume (translations mm, rotations rad). */
export function truthParameters() {
  return readFileSync(join(phantomDir(), "truth.parameters"), "utf8").trim().split("\n").map((line) => line.trim().split(/\s+/).map(Number));
}
